+    fn visual_cursor_position(
+        &self,
+        selection: &VisualSelection,
+        visible_right_content: &str,
+    ) -> (u16, u16) {
+        let text = self.pane_text_from_visible_right(selection.pane, visible_right_content);
+        let cursor = clamp_text_position(selection.cursor, &text);
+        let Some((x, y, width, height)) = self.pane_inner_rect(selection.pane) else {
+            return (2, 2);
+        };
+        let row = cursor.row.min(usize::from(height.saturating_sub(1))) as u16;
+        let column = cursor.column.min(usize::from(width.saturating_sub(1))) as u16;
+        (y.saturating_add(row).saturating_add(1), x.saturating_add(column).saturating_add(1))
+    }
+
+    fn apply_visual_selection_to_buffer(&self, buffer: &mut Buffer, visible_right_content: &str) {
+        let Some(selection) = &self.visual_selection else {
+            return;
+        };
+        let Some((x, y, width, height)) = self.pane_inner_rect(selection.pane) else {
+            return;
+        };
+        let text = self.pane_text_from_visible_right(selection.pane, visible_right_content);
+        for (row, start, end) in selection_row_ranges(selection, &text, false) {
+            if row >= usize::from(height) {
+                continue;
+            }
+            let start = start.min(usize::from(width));
+            let end = end.min(usize::from(width));
+            for column in start..end {
+                let cell = buffer.get_mut(x + column as u16, y + row as u16);
+                cell.modifier.insert(Modifier::REVERSED);
+            }
+        }
+    }

