+fn selection_text(selection: &VisualSelection, text: &PaneText, force_linewise: bool) -> String {
+    selection_row_ranges(selection, text, force_linewise)
+        .into_iter()
+        .filter_map(|(row, start, end)| {
+            let line = text.lines.get(row)?;
+            if force_linewise || selection.mode == VisualMode::Line {
+                Some(line.clone())
+            } else {
+                Some(char_slice(line, start, end))
+            }
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selection_row_ranges(
+    selection: &VisualSelection,
+    text: &PaneText,
+    force_linewise: bool,
+) -> Vec<(usize, usize, usize)> {
+    let anchor = clamp_text_position(selection.anchor, text);
+    let cursor = clamp_text_position(selection.cursor, text);
+    let start_row = anchor.row.min(cursor.row);
+    let end_row = anchor.row.max(cursor.row);
+    let width = text.width.max(1);
+
+    if force_linewise || selection.mode == VisualMode::Line {
+        return (start_row..=end_row)
+            .map(|row| (row, 0, width))
+            .collect();
+    }
+
+    if selection.mode == VisualMode::Block {
+        let start_column = anchor.column.min(cursor.column);
+        let end_column = anchor.column.max(cursor.column).saturating_add(1);
+        return (start_row..=end_row)
+            .map(|row| (row, start_column, end_column))
+            .collect();
+    }
+
+    if anchor.row == cursor.row {
+        let start_column = anchor.column.min(cursor.column);
+        let end_column = anchor.column.max(cursor.column).saturating_add(1);
+        return vec![(anchor.row, start_column, end_column)];
+    }
+
+    let (first, last) = if (anchor.row, anchor.column) <= (cursor.row, cursor.column) {
+        (anchor, cursor)
+    } else {
+        (cursor, anchor)
+    };
+    let mut ranges = Vec::new();
+    ranges.push((first.row, first.column, width));
+    for row in first.row.saturating_add(1)..last.row {
+        ranges.push((row, 0, width));
+    }
+    ranges.push((last.row, 0, last.column.saturating_add(1)));
+    ranges
+}
+
+fn clamp_text_position(position: TextPosition, text: &PaneText) -> TextPosition {
+    TextPosition {
+        row: position.row.min(text.lines.len().saturating_sub(1)),
+        column: position.column.min(text.width.saturating_sub(1)),
+    }
+}
+
+fn char_slice(line: &str, start: usize, end: usize) -> String {
+    line.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
+
+fn wrapped_content_lines(content: &str, width: usize) -> Vec<String> {
+    let width = width.max(1);
+    let mut rows = Vec::new();
+    for line in content.lines() {
+        push_wrapped_line(line, width, &mut rows);
+    }
+    if content.ends_with('\n') {
+        rows.push(String::new());
+    }
+    rows
+}
+
+fn push_wrapped_line(line: &str, width: usize, rows: &mut Vec<String>) {
+    if line.is_empty() {
+        rows.push(String::new());
+        return;
+    }
+
+    let mut row = String::new();
+    let mut row_width = 0;
+    for ch in line.chars() {
+        row.push(ch);
+        row_width += 1;
+        if row_width == width {
+            rows.push(row);
+            row = String::new();
+            row_width = 0;
+        }
+    }
+    if !row.is_empty() {
+        rows.push(row);
+    }
+}
+
+fn osc52_clipboard_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::new();
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = chunk.get(1).copied().unwrap_or(0);
+        let third = chunk.get(2).copied().unwrap_or(0);
+        encoded.push(TABLE[(first >> 2) as usize] as char);
+        encoded.push(TABLE[(((first & 0b0000_0011) << 4) | (second >> 4)) as usize] as char);
+        if chunk.len() > 1 {
+            encoded.push(TABLE[(((second & 0b0000_1111) << 2) | (third >> 6)) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+        if chunk.len() > 2 {
+            encoded.push(TABLE[(third & 0b0011_1111) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+    }
+    encoded
+}
